<script lang="ts">
  import { onMount } from 'svelte'
  import { ws, fmt, num, stateLabels, type Run } from '../lib/sim.svelte'
  import Trend from '../components/Trend.svelte'
  let tab = $state(0)
  let detailTab = $state(0)
  let search = $state('')
  let status = $state('all')
  let page = $state(0)
  let legacySelected = $state(0)
  let legacySamples = $state<Record<string,unknown>[]>([])
  let legacyOffset = $state(0)
  let rows = $state<Run[]>([])
  let total = $state(0)
  onMount(() => { rows = ws.history; total = ws.historyTotal })
  async function list() { try { const data = await ws.request<{items: Run[]; total: number}>('sim_history', { limit: 50, offset: page * 50, search, status }); rows = data.items; total = data.total } catch { /* shown */ } }
  async function open(id: number) { await ws.loadRun(id); tab = 1 }
  async function oldSamples(index: number, offset = 0) {
    const run = ws.legacyRuns[index]
    if (!run) return
    legacySelected = index + 1
    legacyOffset = offset
    try { legacySamples = (await ws.request<{items:Record<string,unknown>[]}>('sim_legacy_samples', { id: run.id, source_hash: run.source_hash, limit: 100, offset })).items } catch { /* shown */ }
  }
</script>
<p class="lead">实验记录保留启动时配方快照。长曲线按需读取，列表与原始采样分页加载。</p>
<div class="tabs"><button class:active={tab === 0} onclick={() => tab = 0}>实验列表</button><button class:active={tab === 1} onclick={() => tab = 1}>实验详情</button><button class:active={tab === 2} onclick={() => { tab = 2; void ws.loadLegacy() }}>旧库记录</button></div>
{#if tab === 0}<section class="panel"><div class="panel-header"><h2>仿真实验 · {total} 条</h2><button class="button secondary" onclick={list}>刷新列表</button></div><div class="filter-row"><input aria-label="搜索实验" bind:value={search} placeholder="搜索编号或名称" onkeydown={(event) => { if (event.key === 'Enter') { page = 0; void list() } }}/><select aria-label="状态筛选" bind:value={status}><option value="all">全部状态</option>{#each Object.entries(stateLabels) as [key,label]}<option value={key}>{label}</option>{/each}</select><button class="button primary" onclick={() => { page = 0; void list() }}>查询</button><button class="button secondary" onclick={() => { search = ''; status = 'all'; page = 0; void list() }}>清除</button></div><div class="table-wrap"><table><thead><tr><th>编号</th><th>实验名称</th><th>状态</th><th>开始</th><th>结束</th><th>操作</th></tr></thead><tbody>{#each rows as run}<tr><td>#{run.id}</td><td><strong>{run.name}</strong></td><td>{stateLabels[run.state] ?? run.state}</td><td>{fmt(run.started_at)}</td><td>{fmt(run.finished_at)}</td><td><button class="text-button" onclick={() => open(run.id)}>查看详情</button></td></tr>{:else}<tr><td colspan="6" class="empty">没有符合条件的实验</td></tr>{/each}</tbody></table></div><div class="panel-actions"><button class="button secondary" disabled={page === 0} onclick={() => { page--; void list() }}>上一页</button><span>第 {page+1} 页</span><button class="button secondary" disabled={(page+1)*50 >= total} onclick={() => { page++; void list() }}>下一页</button></div></section>{/if}
{#if tab === 1}{#if ws.selectedRun}<section class="panel"><div class="panel-header"><h2>#{ws.selectedRun.id} · {ws.selectedRun.name}</h2><span class="badge">{stateLabels[ws.selectedRun.state] ?? ws.selectedRun.state}</span></div><div class="panel-body"><div class="detail-grid"><div><span>样品</span><strong>{ws.selectedRun.sample.name}</strong></div><div><span>配方快照</span><strong>{ws.selectedRun.recipe_snapshot.name} v{ws.selectedRun.recipe_snapshot.version}</strong></div><div><span>数据来源</span><strong>{ws.selectedRun.source}</strong></div><div><span>开始</span><strong>{fmt(ws.selectedRun.started_at)}</strong></div><div><span>结束</span><strong>{fmt(ws.selectedRun.finished_at)}</strong></div><div><span>复核结论</span><strong>{ws.selectedRun.review_note || '待复核'}</strong></div></div><div class="tabs detail-tabs">{#each ['趋势','原始数据','报警','审计'] as label,i}<button class:active={detailTab === i} onclick={() => detailTab = i}>{label}</button>{/each}</div>
  {#if detailTab === 0}{#if ws.chartSamples.length}<div class="two-charts"><Trend samples={ws.chartSamples} field="temperature_c" label="温度 / ℃"/><Trend samples={ws.chartSamples} field="weight_g" label="质量 / g" color="#f59e0b"/></div><p class="muted">全程趋势按需抽稀至约 300 点；原始数据见“原始数据”子页。</p>{:else}<div class="empty">该实验暂无采样趋势</div>{/if}{/if}
  {#if detailTab === 1}<div class="table-wrap"><table><thead><tr><th>时间</th><th>温度 / ℃</th><th>质量 / g</th><th>质量状态</th></tr></thead><tbody>{#each ws.samples as sample}<tr><td>{fmt(sample.sampled_at)}</td><td>{num(sample.temperature_c,1)}</td><td>{num(sample.weight_g,4)}</td><td>{sample.quality === 'simulated' ? '有效仿真' : sample.reason || sample.quality}</td></tr>{:else}<tr><td colspan="4" class="empty">暂无采样</td></tr>{/each}</tbody></table></div><div class="action-row"><button class="button secondary" disabled={ws.sampleOffset === 0} onclick={() => { ws.sampleOffset = Math.max(0, ws.sampleOffset-300); void ws.loadSamples(ws.selectedRun!.id,false) }}>上一页</button><button class="button secondary" disabled={ws.sampleOffset+300 >= Math.ceil(ws.sampleTotal/ws.sampleStride)} onclick={() => { ws.sampleOffset += 300; void ws.loadSamples(ws.selectedRun!.id,false) }}>下一页</button><label>抽稀倍数<select bind:value={ws.sampleStride} onchange={() => ws.loadSamples(ws.selectedRun!.id)}><option value={1}>全部</option><option value={5}>每 5 点</option><option value={10}>每 10 点</option><option value={50}>每 50 点</option></select></label></div>{/if}
  {#if detailTab === 2}<div class="simple-list">{#each ws.selectedEvents.alarms as a}<div><strong>{a.message}</strong><span>{fmt(a.appeared_at)} · {a.acknowledged_at ? '已确认' : '未确认'}</span></div>{:else}<div>无报警</div>{/each}</div>{/if}
  {#if detailTab === 3}<div class="simple-list">{#each ws.selectedEvents.audit as a}<div><strong>{a.action}</strong><span>{a.detail} · {fmt(a.created_at)}</span></div>{:else}<div>无审计记录</div>{/each}</div>{/if}
  <div class="action-row"><button class="button primary" onclick={() => ws.navigate('analysis')}>查看分析</button><button class="button secondary" onclick={() => ws.navigate('reports')}>生成报告</button></div></div></section>{:else}<div class="empty-state"><h3>请选择实验</h3><button class="button secondary" onclick={() => tab = 0}>返回列表</button></div>{/if}{/if}
{#if tab === 2}<section class="panel"><div class="panel-header"><h2>从旧 SQLite 复制的实验</h2><span class="badge warn">保留来源 · 仅查看</span></div><div class="table-wrap"><table><thead><tr><th>原编号</th><th>名称</th><th>原状态</th><th>原始采样</th><th>开始</th><th>操作</th></tr></thead><tbody>{#each ws.legacyRuns as run,i}<tr><td>#{run.id}</td><td>{run.name}</td><td>{run.status}</td><td>{run.sample_count}</td><td>{fmt(run.started_at)}</td><td><button class="text-button" onclick={() => oldSamples(i)}>查看</button></td></tr>{:else}<tr><td colspan="6" class="empty">暂无导入记录；可在系统设置中导入旧库</td></tr>{/each}</tbody></table></div>{#if legacySelected && ws.legacyRuns[legacySelected-1]}{@const old = ws.legacyRuns[legacySelected-1]}<div class="panel-body"><h3>旧实验 #{old.id} · {old.name}</h3><p class="muted">来源指纹 {old.source_hash.slice(0,16)}；旧库数据原样复制，不作为新版七气体配方。</p><div class="detail-grid"><div><span>原始采样</span><strong>{old.sample_count} 条</strong></div><div><span>报警</span><strong>{old.alarms.length} 条</strong></div><div><span>结束</span><strong>{fmt(old.finished_at)}</strong></div></div><h3 class="section-title">原始采样 · 每页 100 条</h3><div class="table-wrap"><table><thead><tr><th>时间</th><th>温度 / ℃</th><th>质量 / g</th><th>N₂</th><th>H₂</th><th>CO</th></tr></thead><tbody>{#each legacySamples as sample}<tr><td>{String(sample.sampled_at ?? '—')}</td><td>{num(sample.temperature_c as number,1)}</td><td>{num(sample.weight_g as number,4)}</td><td>{num(sample.n2_lpm as number)}</td><td>{num(sample.h2_lpm as number)}</td><td>{num(sample.co_lpm as number)}</td></tr>{:else}<tr><td colspan="6" class="empty">暂无采样</td></tr>{/each}</tbody></table></div><div class="action-row"><button class="button secondary" disabled={legacyOffset === 0} onclick={() => oldSamples(legacySelected-1, Math.max(0, legacyOffset-100))}>上一页</button><button class="button secondary" disabled={legacyOffset+100 >= old.sample_count} onclick={() => oldSamples(legacySelected-1, legacyOffset+100)}>下一页</button></div></div>{/if}</section>{/if}
